+      log.detail(`Copied target file: ${this.options.targetFile}`);
+    } else {
+      log.warn(`Target file not found in repo: ${targetFilePath}`);
+    }
+
+    // Copy related files for broader context
+    await this.copyRelatedFiles(repoDir);
