+    for (const line of lines) {
+      if (line.startsWith('+++ b/')) {
+        const file = line.substring(6).trim();
+        filesChanged.add(file);
+      }
+      if (line.startsWith('+') && !line.startsWith('+++')) {
+        linesAdded++;
+      }
+      if (line.startsWith('-') && !line.startsWith('---')) {
+        linesRemoved++;
+      }
+      if (line.startsWith('@@')) {
